import Foundation

/// One version of an action (spec §5). Generated by codegen from its manifest:
///
///     public enum RenameThingV1: ActionDescriptor {
///         public static let action = "rename-thing"
///         public static let version = 1
///         public struct Input: Codable, … { … }
///         public struct Result: Codable, … { … }
///         public enum DeclaredError: DeclaredActionError { case nameTaken(NameTakenDetails), locked … }
///     }
public protocol ActionDescriptor: Sendable {
    associatedtype Input: Encodable & Sendable
    associatedtype Result: Decodable & Sendable
    associatedtype DeclaredError: DeclaredActionError

    static var action: String { get }
    static var version: Int { get }
}

/// An action's declared errors: the outcomes callers handle, such as a name that's taken. Generated
/// as an enum with a case per code.
public protocol DeclaredActionError: Sendable, Equatable {
    /// The codes this action version declares.
    static var codes: [String] { get }
    /// The error for a declared code, decoding its details.
    init(code: String, details: JSONValue?) throws
    /// This error's code.
    var code: String { get }
    /// This error's details, as sent on the wire.
    var details: JSONValue? { get }
}

/// For actions that declare no errors.
public enum NoDeclaredError: DeclaredActionError {
    public static let codes: [String] = []
    public init(code: String, details: JSONValue?) throws {
        throw ActionFailure(status: 200, code: code, body: Data())
    }

    public var code: String { switch self {} }
    public var details: JSONValue? { switch self {} }
}

/// How an action call ended, when the composer performed it: its result and effects, or one of its
/// declared errors. Anything else is thrown as `ActionFailure`.
public enum ActionOutcome<Result: Sendable, DeclaredError: DeclaredActionError>: Sendable {
    case ok(Result, ActionEffects)
    case error(DeclaredError)

    /// The result, if the action succeeded.
    public var result: Result? {
        if case .ok(let result, _) = self { return result }
        return nil
    }

    /// The declared error, if the action ended with one.
    public var declaredError: DeclaredError? {
        if case .error(let error) = self { return error }
        return nil
    }
}

/// The composer didn't perform the action, or answered with something the app can't use: a protocol
/// error such as `unauthenticated` or `invalid_input`, a failure in front of the composer, or an
/// error code the action doesn't declare (spec §5.1). Show a generic message.
public struct ActionFailure: Error, Sendable, Equatable {
    /// The HTTP status.
    public let status: Int
    /// The protocol error code, or the undeclared error code, if there is one.
    public let code: String?
    public let body: Data

    public init(status: Int, code: String?, body: Data) {
        self.status = status
        self.code = code
        self.body = body
    }
}

/// A screen request failed (spec §4.3). `code` tells not found, unauthenticated and forbidden apart.
public struct ScreenError: Error, Sendable, Equatable {
    /// The HTTP status.
    public let status: Int
    /// The protocol error code, e.g. "not_found", if the body has one.
    public let code: String?
    public let body: Data

    public init(status: Int, code: String?, body: Data) {
        self.status = status
        self.code = code
        self.body = body
    }

    public var isNotFound: Bool { code == "not_found" }
    public var isUnauthenticated: Bool { code == "unauthenticated" }
    public var isForbidden: Bool { code == "forbidden" }
}
